 useEffect(()=>{let alive=true,inFlight=false;async function refresh(){if(inFlight||latestJobs.current.some(j=>j.status==='running'&&['metadata','scan'].includes(j.kind)))return;inFlight=true;try{const status=await api('/com/status');if(alive)setCom(status);}catch{}finally{inFlight=false;}}const timer=setInterval(refresh,20000);return()=>{alive=false;clearInterval(timer);};},[]);
