 async function run(work:()=>Promise<any>,success=''){
  setBusy(true);setError('');
  try{const result=await work();if(result?.kind&&result?.id)setPreview(result);else if(result?.job){setNotice('Operation queued. Follow its progress in Queue.');setRevision(r=>r+1);}else if(success)setNotice(success);return result;}
  catch(e){setError(e instanceof Error?e.message:String(e));return null;}
  finally{setBusy(false);}
 }
 async function connectLive(){await run(async()=>{const status=await api('/com/status');setCom(status);if(!status.available)throw new Error(status.reason||'Open classic iTunes first.');const existing=profiles.find(p=>p.config.kind==='live'&&p.config.library_pid===status.library_pid);if(existing){setProfile(existing.id);return existing.scanned?null:api(`/profiles/${existing.id}/scan`,'POST');}const added=await api('/profiles','POST',{name:status.xml_path?.split(/[\\/]/).slice(-2,-1)[0]||status.library_name||'Current iTunes library',kind:'live',source:'',library_pid:status.library_pid||''});await loadProfiles();setProfile(added.id);return added;});}
 async function removeLibrary(identity:string){const item=profiles.find(p=>p.id===identity);if(!window.confirm(`🗑️ Remove ${item?.name||'this library'} from the app? Music files, saved copies and undo records will stay.`))return;await run(async()=>{await api(`/profiles/${identity}/remove`,'POST',{confirmed:true});loadedViews.current.delete(identity);const list=await loadProfiles();if(useWorkspace.getState().profile===identity)setProfile(list[0]?.id||'');},'Library removed.');}
