 async function loadProfiles(){const p=await api('/profiles');setProfiles(p);const current=useWorkspace.getState().profile;if(current&&!p.some((x:any)=>x.id===current))setProfile(p[0]?.id||'');return p;}
 useEffect(()=>{document.documentElement.dataset.theme=theme;},[theme]);
 useEffect(()=>{run(async()=>{const initial=await loadProfiles();if(!useWorkspace.getState().profile&&initial.length)setProfile(initial[0].id);setCom(await api('/com/status'));setDiscovery(await api('/discovery'));const p=await api('/settings');setPrefs(p);if(p.theme)setTheme(p.theme);if(p.template)setTemplate(p.template);setRules(await api('/rules'));setChangelog((await api('/changelog')).text);});},[]);
 useEffect(()=>{const t=setTimeout(()=>{setDebounced(search);setPage(0);},120);return()=>clearTimeout(t);},[search]);
