 function toggle(id:number){setSelected(s=>{const next=new Set(s);next.has(id)?next.delete(id):next.add(id);return next;});}
 function selectLibraryRow(id:number,shift:boolean,additive:boolean,checked?:boolean){setSelected(current=>{const next=new Set(current);if(shift&&lastLibrarySelected.current!==null){const a=libraryIds.indexOf(lastLibrarySelected.current),b=libraryIds.indexOf(id);if(a>=0&&b>=0){const range=libraryIds.slice(Math.min(a,b),Math.max(a,b)+1);if(!additive)next.clear();range.forEach(value=>next.add(value));return next;}}if(checked!==undefined){checked?next.add(id):next.delete(id);return next;}if(additive){next.has(id)?next.delete(id):next.add(id);return next;}return new Set([id]);});if(!shift)lastLibrarySelected.current=id;}
